<template>
  <div>
    <div class="flex flex-wrap gap-1">
      <Button
        v-for="value in values"
        ref="emails"
        :key="value"
        :label="value"
        theme="gray"
        variant="subtle"
        @keydown.delete.capture.stop="removeLastValue"
      >
        <template #suffix>
          <FeatherIcon
            class="h-3.5"
            name="x"
            @click.stop="removeValue(value)"
          />
        </template>
      </Button>
      <div class="flex-1">
        <Combobox v-model="selectedValue" nullable>
          <Popover v-model:show="showOptions" class="w-full">
            <template #target="{ togglePopover }">
              <ComboboxInput
                ref="search"
                class="search-input form-input w-full border-none bg-surface-white hover:bg-surface-white focus:border-none focus:!shadow-none focus-visible:!ring-0"
                type="text"
                :value="query"
                autocomplete="off"
                @change="
                  (e) => {
                    query = e.target.value;
                    showOptions = true;
                  }
                "
                @focus="() => togglePopover()"
                @keydown.delete.capture.stop="removeLastValue"
              />
            </template>
            <template #body="{ isOpen }">
              <div v-show="isOpen">
                <div
                  class="mt-1 rounded-lg bg-surface-white py-1 text-base shadow-2xl"
                >
                  <ComboboxOptions
                    class="my-1 max-h-[12rem] overflow-y-auto px-1.5"
                    static
                  >
                    <ComboboxOption
                      v-for="option in options"
                      :key="option.value"
                      v-slot="{ active }"
                      :value="option"
                    >
                      <li
                        :class="[
                          'flex cursor-pointer items-center rounded px-2 py-1 text-base',
                          { 'bg-surface-gray-2': active },
                        ]"
                      >
                        <UserAvatar
                          class="me-2"
                          :name="getUsernameLabel(option.value)"
                          size="lg"
                        />
                        <div class="flex flex-col gap-1 p-1 text-ink-gray-8">
                          <div class="text-base font-medium">
                            {{ getUsernameLabel(option.label) }}
                          </div>
                          <div class="text-sm text-ink-gray-5">
                            {{ option.value }}
                          </div>
                        </div>
                      </li>
                    </ComboboxOption>
                  </ComboboxOptions>
                </div>
              </div>
            </template>
          </Popover>
        </Combobox>
      </div>
    </div>
    <ErrorMessage v-if="error" class="mt-2 ps-2" :message="error" />
  </div>
</template>

<script setup lang="ts">
import { UserAvatar } from "@/components/";
import {
  Combobox,
  ComboboxInput,
  ComboboxOption,
  ComboboxOptions,
} from "@headlessui/vue";
import { watchDebounced } from "@vueuse/core";
import { Popover, createResource } from "frappe-ui";
import { computed, nextTick, ref } from "vue";

const props = defineProps({
  validate: {
    type: Function,
    default: null,
  },
  errorMessage: {
    type: Function,
    default: (value) => `${value} is an Invalid value`,
  },
});

const values = defineModel();

const emails = ref([]);
const search = ref(null);
const error = ref(null);
const query = ref("");
const text = ref("");
const showOptions = ref(false);

const selectedValue = computed({
  get: () => query.value || "",
  set: (val) => {
    query.value = "";
    if (val) {
      showOptions.value = false;
    }
    val?.value && addValue(val.value);
  },
});

watchDebounced(
  query,
  (val) => {
    val = val || "";
    if (text.value === val) return;
    text.value = val;
    reload(val);
  },
  { debounce: 400, immediate: true }
);

const filterOptions = createResource({
  url: "helpdesk.api.contact.search_contacts",
  method: "GET",
  cache: ["Contact", text.value],
  params: {
    txt: text.value,
  },
  transform: (data: Record<"full_name" | "name" | "email_id", string>[]) => {
    return data.map(({ full_name, email_id, name }) => ({
      label: full_name || name || email_id,
      value: email_id,
    }));
  },
});

const options = computed(() => {
  let searchedContacts = filterOptions.data || [];
  if (!searchedContacts.length && query.value) {
    searchedContacts.push({
      label: query.value,
      value: query.value,
    });
  }
  return searchedContacts;
});

function reload(val) {
  filterOptions.update({
    params: {
      txt: val,
    },
  });
  filterOptions.reload();
}

const normalizeAndFilter = (field) => {
  let arr = [];
  let current = "";
  let inQuotes = false;

  for (let char of field) {
    if (char === '"') {
      inQuotes = !inQuotes;
      current += char;
    } else if (char === "," && !inQuotes) {
      if (current.trim()) {
        arr.push(current.trim());
      }
      current = "";
    } else {
      current += char;
    }
  }
  if (current.trim()) {
    arr.push(current.trim());
  }

  return arr;
};

const addValue = (value) => {
  error.value = null;
  if (value) {
    const splitValues = normalizeAndFilter(value);
    splitValues.forEach((value) => {
      value = value.trim();
      if (value) {
        // check if value is not already in the values array
        if (!values.value?.includes(value)) {
          // check if value is valid
          if (value && props.validate && !props.validate(value)) {
            error.value = props.errorMessage(value);
            return;
          }
          // add value to values array
          if (!values.value) {
            values.value = [value];
          } else {
            values.value.push(value);
          }
          value = value.replace(value, "");
        }
      }
    });
    !error.value && (value = "");
  }
};
const getUsernameLabel = (value: string) => {
  if (!value) return "";

  // Take everything before '<'
  const beforeAngle = value.split("<")[0];

  // Remove quotes and trim
  return beforeAngle.replace(/"/g, "").trim();
};

const removeValue = (value) => {
  values.value = values.value.filter((v) => v !== value);
};

function removeLastValue() {
  if (query.value) return;
  let emailRef = emails.value[emails.value.length - 1]?.rootRef;
  if (document.activeElement === emailRef) {
    values.value.pop();
    nextTick(() => {
      if (values.value.length) {
        emailRef = emails.value[emails.value.length - 1].rootRef;
        emailRef?.focus();
      } else {
        setFocus();
      }
    });
  } else {
    emailRef?.focus();
  }
}

function setFocus() {
  search.value?.focus?.();
}

defineExpose({ setFocus });
</script>
